    std::chrono::steady_clock::time_point begin = std::chrono::steady_clock::now();
    // The query starts executing and takes ~15s. During this time we expect to see numThreads as numThreads + 2.
    auto result = connection->query("PROJECT GRAPH PK (person, knows)   MATCH (a:Person) WHERE a.ID = 1   CALL shortest_paths(PK, a, " +
                                        std::to_string(distance) + ",  true) RETURN length, count(*);");
    std::chrono::steady_clock::time_point end = std::chrono::steady_clock::now();

    // Print query result.
